class MockLockFile:

    def __init__(self):
        self.data = {'dependencies': [{'name': 'requests', 'version': '2.28.1', 'source': 'pypi'}, {'name': 'click', 'version': '8.1.3', 'source': 'pypi'}], 'groups': {'default': ['requests', 'click']}}

    def select(self, environment, tags, extras, dependency_groups, prefer_sdist_predicate):
        if not dependency_groups:
            dependency_groups = ['default']
        selected = []
        for group in dependency_groups:
            if group in self.data['groups']:
                for dep_name in self.data['groups'][group]:
                    for dep in self.data['dependencies']:
                        if dep['name'] == dep_name:
                            selected.append(dep)
        return selected

class MockSdist:

    def __init__(self, filename):
        self._filename = filename

    @property
    def filename(self):
        return self._filename
